using System;using System.Linq;using System.IO;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal sealed partial class DiskAnalyzerWindow {
  internal void VerifyVirtualTree(Action<bool,string> check){var original=Result;try{var root=new DiskFolder{Path=@"D:\Example",Bytes=12000,Files=12000};for(int i=0;i<12000;i++)root.Children.Add(new DiskFolder{Path=@"D:\Example\Folder-"+i.ToString("D5"),Parent=root,Bytes=1,Files=1});Present(new DiskAnalysis{Root=root});UpdateLayout();NavigationTests.Wait(Task.Delay(100));UpdateLayout();var item=(TreeViewItem)Folders.Items[0];int realized=AdvancedToolsTests.Visual<TreeViewItem>(Folders).Count();check(item.Items.Count==12000&&realized<250,"Tree virtualizes 12,000 directory models into fewer than 250 visible containers (actual "+realized+")");var scroll=AdvancedToolsTests.Visual<ScrollViewer>(Folders).First();scroll.ScrollToBottom();NavigationTests.Wait(Task.Delay(100));UpdateLayout();check(AdvancedToolsTests.Visual<TreeViewItem>(Folders).Count()<250,"Scrolling preserves directory-container virtualization");check(AdvancedToolsTests.Visual<TextBlock>(Folders).Any(x=>x.Text.Contains("11999")),"Virtualized tree can display the last directory");}finally{Present(original);}}
  internal void DrawHelpDemo(string root){ScanRoots.Text=@"D:\Example\Documents";scope.Text=@"D:\Example\Documents";tabs.SelectedIndex=0;PendingParameters=false;if(lastAnalysisStatus!=null)status.Text=lastAnalysisStatus;UpdateLayout();NextStageTests.Draw(this,Path.Combine(root,"treemap.png"));}
 }
}
